import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        long n = nextLong();
        // Every earlier element contributes a[i] - a[j], so counter[i] = i * a[i] - prefix sum.
        long prefix = 0;
        StringBuilder sb = new StringBuilder();
        for (long i = 0; i < n; i++) {
            long v = nextLong();
            sb.append(i * v - prefix).append(i + 1 < n ? ' ' : '\n');
            prefix += v;
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := nextInt()
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer w.Flush()
	// Every earlier element contributes a[i] - a[j], so counter[i] = i * a[i] - prefix sum.
	prefix := int64(0)
	for i := int64(0); i < n; i++ {
		v := nextInt()
		w.WriteString(strconv.FormatInt(i*v-prefix, 10))
		if i+1 < n {
			w.WriteByte(' ')
		} else {
			w.WriteByte('\n')
		}
		prefix += v
	}
}
